<body>
<div id="app" class="app">
  <div class="wrap">
    <header>
      <div class="brand">Pomofocus</div>
      <div class="head-actions">
        <button class="btn icon-btn" title="Reports" onclick="noop()">▥</button>
        <button class="btn icon-btn" title="Settings" onclick="noop()">⚙</button>
        <button class="btn icon-btn" title="Account" onclick="noop()">●</button>
        <button class="btn icon-btn" title="More" onclick="toggleMenu()">⋮</button>
      </div>
    </header>
    <div id="dropdown" class="dropdown">
      <button class="btn" onclick="clearTasks()">Clear finished tasks</button>
      <button class="btn" onclick="alert('Settings')">Settings</button>
      <button class="btn" onclick="alert('Keyboard shortcuts')">Keyboard shortcuts</button>
    </div>

    <section class="timer-card">
      <div class="modes">
        <button class="btn mode active" data-mode="pomodoro" onclick="setMode('pomodoro')">Pomodoro</button>
        <button class="btn mode" data-mode="short" onclick="setMode('short')">Short Break</button>
        <button class="btn mode" data-mode="long" onclick="setMode('long')">Long Break</button>
      </div>
      <div id="time" class="time">25:00</div>
      <button id="start" class="btn start" onclick="toggleTimer()">START</button><span id="skip" class="skip btn" onclick="skipTimer()">▶|</span>
    </section>

    <div class="session"><small>#1</small><span id="sessionText">Time to focus!</span></div>

    <section class="tasks">
      <div class="tasks-head"><h2>Tasks</h2><button class="btn task-menu" onclick="toggleMenu()">⋮</button></div>
      <div class="rule"></div>
      <div id="taskArea">
        <button class="btn add-task" onclick="openEditor()">⊕&nbsp; Add Task</button>
      </div>
      <div id="summary" class="pomodoro-summary" style="display:none">Pomos: <b>0 / 1</b>&nbsp;&nbsp; Finish At: <b>14:57</b> (0h)</div>
    </section>
  </div>
</div>

<section class="info" id="info" style="display:none">
  <div class="wrap">
    <h1>An online Pomodoro Timer to boost<br>your productivity</h1>
    <h2>What is Pomofocus?</h2>
    <p>Pomofocus is a customizable pomodoro timer that works on desktop &amp; mobile browser. The aim of this app is to help you focus on any task you are working on, such as study, writing, or coding. This app is inspired by <a>Pomodoro Technique</a> which is a time management method developed by Francesco Cirillo.</p>
  </div>
</section>

<script>
let mode='pomodoro', seconds=1500, timer=null, running=false, task=null, editor=false, completed=false;
const app=document.getElementById('app'), timeEl=document.getElementById('time'), startEl=document.getElementById('start');
function noop(){}
function setMode(m){
  if(running)return;
  mode=m; seconds=m==='pomodoro'?1500:m==='short'?300:900;
  app.className='app '+(m==='short'?'break':m==='long'?'long':'');
  document.querySelectorAll('.mode').forEach(x=>x.classList.toggle('active',x.dataset.mode===m));
  document.getElementById('sessionText').textContent=m==='pomodoro'?'Time to focus!':'Time for a break!';
  updateTime();
}
function updateTime(){let s=seconds;timeEl.textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function toggleTimer(){
  if(running){clearInterval(timer);running=false;startEl.textContent='START';document.getElementById('skip').style.display='none';return}
  running=true;startEl.textContent='PAUSE';document.getElementById('skip').style.display='inline-block';
  timer=setInterval(()=>{seconds--;updateTime();if(seconds<=0){clearInterval(timer);running=false;startEl.textContent='START';completeTimer()}},1000)
}
function skipTimer(){clearInterval(timer);running=false;startEl.textContent='START';setMode(mode==='pomodoro'?'short':'pomodoro')}
function openEditor(){
  editor=true; document.getElementById('info').style.display='block';
  renderTasks();
  setTimeout(()=>document.querySelector('.task-input')?.focus(),30)
}
function renderTasks(){
  const area=document.getElementById('taskArea');
  let html='';
  if(task) html+=`<div class="task-row ${completed?'done':''}"><span class="btn check" onclick="toggleDone()">✓</span><span class="task-name">${task}</span><span class="count">0 / 1</span><button class="btn row-more">⋮</button></div>`;
  if(editor) html+=`<div class="editor"><div class="editor-main"><input class="task-input" id="taskInput" placeholder="What are you working on?" value="${task||''}"><div class="est">Est Pomodoros</div><div class="est-row"><input class="estimate" value="1"><button class="btn arrow">⌃</button><button class="btn arrow">⌄</button></div><div class="links">＋ Add Note&nbsp;&nbsp; ＋ Add Project&nbsp; 🔒</div></div><div class="editor-foot"><button class="btn cancel" onclick="cancelEditor()">Cancel</button><button class="btn save" onclick="saveTask()">Save</button></div></div>`;
  if(!editor && !task) html='<button class="btn add-task" onclick="openEditor()">⊕&nbsp; Add Task</button>';
  if(!editor && task) html+='<button class="btn add-task" onclick="openEditor()">⊕&nbsp; Add Task</button>';
  area.innerHTML=html;
  document.getElementById('summary').style.display=task?'block':'none';
}
function saveTask(){
  const input=document.getElementById('taskInput'); if(!input||!input.value.trim())return;
  task=input.value.trim(); editor=false; renderTasks();
}
function cancelEditor(){editor=false;renderTasks();if(!task)document.getElementById('info').style.display='none'}
function toggleDone(){completed=!completed;renderTasks();if(completed){document.getElementById('summary').innerHTML='Pomos: <b>0 / 0</b>&nbsp;&nbsp; Finish At: <b>14:32</b> (0h)';showToast()}}
function showToast(){
  if(document.querySelector('.toast'))return;
  const t=document.createElement('div');t.className='toast';t.innerHTML=`<span>You've finished all your tasks for today 🎉</span><button class="btn" onclick="clearTasks()">Clear Tasks</button>`;document.body.appendChild(t)
}
function clearTasks(){
  task=null;completed=false;editor=false;document.querySelector('.toast')?.remove();document.getElementById('info').style.display='none';renderTasks();makeConfetti()
}
function toggleMenu(){const d=document.getElementById('dropdown');d.style.display=d.style.display==='block'?'none':'block'}
function completeTimer(){if(task){completed=true;renderTasks();showToast()}else makeConfetti()}
function makeConfetti(){
  const box=document.createElement('div');box.className='confetti';
  const colors=['#fff','#f7d35c','#48cf80','#42a5f5','#d65fe8','#ff8b4d'];
  for(let i=0;i<80;i++){let x=document.createElement('i');x.style.left=Math.random()*100+'%';x.style.top=(Math.random()*25+20)+'%';x.style.background=colors[i%colors.length];x.style.animationDelay=Math.random()*.8+'s';x.style.transform=`rotate(${Math.random()*360}deg)`;box.appendChild(x)}
  document.body.appendChild(box);setTimeout(()=>box.remove(),3000)
}
updateTime();
</script>
</body>
</html>
